CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,disabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(organization_id uuid REFERENCES organizations ON DELETE CASCADE,user_id uuid REFERENCES users ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('owner','admin','developer','viewer')),PRIMARY KEY(organization_id,user_id));
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations,name text NOT NULL,max_outstanding int NOT NULL DEFAULT 20 CHECK(max_outstanding BETWEEN 1 AND 100),max_daily int NOT NULL DEFAULT 1000,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE api_keys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects,name text NOT NULL,prefix text NOT NULL,secret_hash text UNIQUE NOT NULL,scopes text[] NOT NULL,expires_at timestamptz,revoked_at timestamptz,last_used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE runtimes(id text PRIMARY KEY,language text NOT NULL,version text NOT NULL,image text NOT NULL,enabled boolean NOT NULL DEFAULT true,UNIQUE(language,version));
CREATE TABLE workers(id text PRIMARY KEY,status text NOT NULL DEFAULT 'online',slots int NOT NULL CHECK(slots>0),memory_mb int NOT NULL,hostname text NOT NULL,last_heartbeat timestamptz NOT NULL DEFAULT now());
CREATE TABLE worker_runtimes(worker_id text REFERENCES workers ON DELETE CASCADE,runtime_id text REFERENCES runtimes,PRIMARY KEY(worker_id,runtime_id));
CREATE TABLE challenges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid REFERENCES projects,slug text UNIQUE NOT NULL,title text NOT NULL,description text NOT NULL,difficulty text NOT NULL CHECK(difficulty IN ('easy','medium','hard')),judge text NOT NULL DEFAULT 'whitespace',visibility text NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','private')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE challenge_test_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),challenge_id uuid NOT NULL REFERENCES challenges ON DELETE CASCADE,position int NOT NULL,stdin text NOT NULL,expected text NOT NULL,hidden boolean NOT NULL DEFAULT true,weight int NOT NULL DEFAULT 1,UNIQUE(challenge_id,position));
CREATE TABLE submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects,user_id uuid REFERENCES users,runtime_id text NOT NULL REFERENCES runtimes,challenge_id uuid REFERENCES challenges,source text NOT NULL,stdin text NOT NULL,mode text NOT NULL CHECK(mode IN ('run','challenge')),limits jsonb NOT NULL,state text NOT NULL CHECK(state IN ('created','queued','scheduled','preparing','compiling','running','judging','completed','failed','cancelled','timed_out')),worker_id text REFERENCES workers,attempt int NOT NULL DEFAULT 0,cancel_requested boolean NOT NULL DEFAULT false,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX submissions_schedule ON submissions(state,created_at);
CREATE INDEX submissions_project_history ON submissions(project_id,created_at DESC,id);
CREATE TABLE submission_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,submission_id uuid NOT NULL REFERENCES submissions,state text NOT NULL,worker_id text,reason text NOT NULL,duration_ms int,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX submission_events_timeline ON submission_events(submission_id,id);
CREATE TABLE submission_results(submission_id uuid PRIMARY KEY REFERENCES submissions,verdict text NOT NULL,stdout text NOT NULL,stderr text NOT NULL,compile_output text NOT NULL DEFAULT '',exit_code int,wall_ms int NOT NULL,cpu_ms int NOT NULL,peak_memory_bytes bigint NOT NULL,output_truncated boolean NOT NULL DEFAULT false,score float NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE test_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),submission_id uuid NOT NULL REFERENCES submissions,test_case_id uuid NOT NULL REFERENCES challenge_test_cases,verdict text NOT NULL,wall_ms int NOT NULL,peak_memory_bytes bigint NOT NULL,UNIQUE(submission_id,test_case_id));
CREATE TABLE usage_records(submission_id uuid PRIMARY KEY REFERENCES submissions,project_id uuid NOT NULL REFERENCES projects,wall_ms int NOT NULL,cpu_ms int NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE drafts(user_id uuid REFERENCES users,challenge_id uuid REFERENCES challenges,runtime_id text REFERENCES runtimes,source text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,challenge_id,runtime_id));
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id uuid REFERENCES users,organization_id uuid REFERENCES organizations,action text NOT NULL,target text,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_endpoints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects,url text NOT NULL,secret text NOT NULL,enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),endpoint_id uuid NOT NULL REFERENCES webhook_endpoints,submission_id uuid NOT NULL REFERENCES submissions,event text NOT NULL,payload jsonb NOT NULL,attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'pending',response_code int,UNIQUE(endpoint_id,submission_id,event));
CREATE TABLE dispatch_outbox(submission_id uuid PRIMARY KEY REFERENCES submissions,worker_id text NOT NULL REFERENCES workers,attempt int NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
